INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Subnetzanzahl immer eine Potenz von 2?', 2, '[{"text": "Ja", "correct": true, "because": "Formel 2^n"}, {"text": "Nein", "correct": false, "because": "Bits sind binär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze bekomme ich mit 3 geliehenen Bits?', 3, '[{"text": "8", "correct": true, "because": "2^3 = 8"}, {"text": "6", "correct": false, "because": "Nicht binär"}, {"text": "9", "correct": false, "because": "Falsche Potenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formel nutze ich für die Anzahl der Subnetze?', 4, '[{"text": "2^n", "correct": true, "because": "n = geliehene Bits"}, {"text": "n^2", "correct": false, "because": "Nicht exponentiell"}, {"text": "2n", "correct": false, "because": "Lineare Formel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 4 Bits ergeben 16 Subnetze. b) n ist die Anzahl geliehener Bits.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "2^4 = 16, n definiert"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Berechnung der Subnetzanzahl?', 5, '[{"text": "Hostanzahl", "correct": true, "because": "Nur geliehene Bits zählen"}, {"text": "Anzahl geliehener Bits", "correct": false, "because": "Kern der Formel"}, {"text": "Präfixlänge", "correct": false, "because": "Bestimmt n"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2 geliehene Bits 4 Subnetze ergeben?', 2, '[{"text": "Ja", "correct": true, "because": "2^2 = 4"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze entstehen bei 5 geliehenen Bits?', 3, '[{"text": "32", "correct": true, "because": "2^5 = 32"}, {"text": "25", "correct": false, "because": "Nicht binär"}, {"text": "10", "correct": false, "because": "Falsche Potenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen die Subnetzanzahl?', 5, '[{"text": "Geliehene Bits", "correct": true, "because": "n in 2^n"}, {"text": "Präfixänderung", "correct": true, "because": "Definiert geliehene Bits"}, {"text": "Hostanzahl", "correct": false, "because": "Separat berechnet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2^n gilt nur für IPv6. b) n kann 0 sein. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) auch IPv4, b) mindestens 1"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide sind falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Subnetzanzahl?', 4, '[{"text": "Geliehene Bits", "correct": false, "because": "Kern der Berechnung"}, {"text": "Präfix", "correct": false, "because": "Bestimmt n"}, {"text": "Bandbreite", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ergeben 1 geliehene Bit 2 Subnetze?', 2, '[{"text": "Ja", "correct": true, "because": "2^1 = 2"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte beeinflussen die Anzahl der Subnetze?', 4, '[{"text": "Anzahl geliehener Bits", "correct": true, "because": "n in 2^n"}, {"text": "Ursprünglicher Präfix", "correct": true, "because": "Basis für n"}, {"text": "Interface-ID", "correct": false, "because": "Host-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 6 Bits 64 Subnetze ergeben. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "2^6 = 64"}, {"text": "Nein", "correct": false, "because": "Formel bestätigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Subnetzberechnung?', 3, '[{"text": "Anzahl geliehener Bits", "correct": true, "because": "Bestimmt 2^n"}, {"text": "Hostanzahl", "correct": false, "because": "Separat"}, {"text": "Kürzeste Adresse", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 3 Bits = 8 Subnetze. b) n ist immer positiv.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "2^3 = 8, n ≥ 1"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse erwartest du bei diesen Werten?', 5, '[{"text": "2 Bits = 4 Subnetze", "correct": true, "because": "2^2 = 4"}, {"text": "4 Bits = 16 Subnetze", "correct": true, "because": "2^4 = 16"}, {"text": "3 Bits = 6 Subnetze", "correct": false, "because": "2^3 = 8"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Subnetzanzahl unwichtig?', 3, '[{"text": "Geliehene Bits", "correct": false, "because": "Kern der Formel"}, {"text": "Präfixlänge", "correct": false, "because": "Basis für n"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind 0 geliehene Bits möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Mindestens 1 Bit nötig"}, {"text": "Ja", "correct": false, "because": "2^0 = 1, aber kein Subnetting"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 7 Bits 128 Subnetze ergeben?', 3, '[{"text": "Ja", "correct": true, "because": "2^7 = 128"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitanzahl wähle ich für 256 Subnetze?', 4, '[{"text": "8", "correct": true, "because": "2^8 = 256"}, {"text": "6", "correct": false, "because": "2^6 = 64"}, {"text": "10", "correct": false, "because": "2^10 = 1024"}]');
